{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "Fasudil, the closest analogue sharing the same sulfonyl-homopiperazine core, has an absolute oral bioavailability of 69% in humans, directly supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "SB-742457, a sulfone/piperazine-containing heteroaromatic, showed excellent oral bioavailability in phase III trials, supporting high oral absorption for this sulfonamide-piperazine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Eltoprazine, a small piperazine drug, has about 95% absolute oral bioavailability, indicating that ionizable piperazine-containing small molecules can be very well absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Baricitinib, a small polar drug with basic heterocyclic features, has about 80% absolute oral bioavailability, supporting that polarity and ionization do not preclude high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest and most transferable evidence, fasudil, shows 69% absolute oral bioavailability in humans despite a similar ionizable homopiperazine sulfonamide. Additional piperazine/sulfone-containing drugs with high oral bioavailability reinforce this pattern. Weak negative evidence from less similar aryl piperazines is outweighed, so the query is predicted to have F ≥ 20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query itself (hydroxyfasudil).",
    "The impact of the 1-oxo/lactam modification on permeability and first-pass metabolism relative to fasudil is not directly quantified."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

